import{_ as c,C as a,o as i,c as r,a4 as o,E as t}from"./chunks/framework.YC5CMuPM.js";const f=JSON.parse('{"title":"Modules","description":"","frontmatter":{},"headers":[],"relativePath":"reference/modules.md","filePath":"reference/modules.md","lastUpdated":1790665980000}'),n={name:"reference/modules.md"};function s(l,e,u,p,h,m){const d=a("ModuleTable");return i(),r("div",null,[e[0]||(e[0]=o('<h1 id="modules" tabindex="-1">Modules <a class="header-anchor" href="#modules" aria-label="Permalink to &quot;Modules&quot;">​</a></h1><p><strong>One section per module, grouped by role, with the classes you will meet first.</strong> The purpose column and dependencies below are generated from each module&#39;s header.<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup> The notes underneath are hand-written. For the visual version, see the <a href="./module-map.html">module map</a>.</p>',2)),t(d),e[1]||(e[1]=o('<h2 id="foundation" tabindex="-1">Foundation <a class="header-anchor" href="#foundation" aria-label="Permalink to &quot;Foundation&quot;">​</a></h2><p>These modules have no GUI or audio code. Anything can use them, including command-line tools and servers.</p><h3 id="juce-core" tabindex="-1">juce_core <a class="header-anchor" href="#juce-core" aria-label="Permalink to &quot;juce_core {#juce-core}&quot;">​</a></h3><p>The base of everything, with no dependencies of its own. It covers what the C++ standard library does (and in JUCE&#39;s early days didn&#39;t), plus OS services.</p><ul><li><strong>Text</strong>: <code>String</code>, <code>StringArray</code>, <code>Identifier</code>, <code>StringRef</code>, <code>CharPointer_UTF8</code></li><li><strong>Containers</strong>: <code>Array</code>, <code>OwnedArray</code>, <code>ReferenceCountedArray</code>, <code>HashMap</code>, <code>var</code>, <code>DynamicObject</code>, <code>ListenerList</code>, <code>AbstractFifo</code></li><li><strong>Memory</strong>: <code>HeapBlock</code>, <code>MemoryBlock</code>, <code>ReferenceCountedObject</code>, <code>WeakReference</code>, leak detector</li><li><strong>Files and streams</strong>: <code>File</code>, <code>FileInputStream</code>, <code>MemoryOutputStream</code>, <code>ZipFile</code>, <code>GZIPCompressorOutputStream</code></li><li><strong>Threads</strong>: <code>Thread</code>, <code>ThreadPool</code>, <code>CriticalSection</code>, <code>SpinLock</code>, <code>WaitableEvent</code>, <code>ChildProcess</code></li><li><strong>Data formats</strong>: <code>XmlElement</code>, <code>XmlDocument</code>, <code>JSON</code></li><li><strong>Network</strong>: <code>URL</code>, <code>WebInputStream</code>, <code>StreamingSocket</code>, <code>DatagramSocket</code></li><li><strong>Misc</strong>: <code>Time</code>, <code>RelativeTime</code>, <code>Random</code>, <code>Uuid</code>, <code>SystemStats</code>, <code>Logger</code>, <code>UnitTest</code></li></ul><p><em>Start here:</em> <code>String</code>, <code>File</code>, <code>Array</code>, and <code>Thread</code>. You&#39;ll use them in every project.</p><h3 id="juce-events" tabindex="-1">juce_events <a class="header-anchor" href="#juce-events" aria-label="Permalink to &quot;juce_events {#juce-events}&quot;">​</a></h3><p>The <strong>message loop</strong> and everything asynchronous.</p><ul><li><code>MessageManager</code>: runs the event loop; <code>callAsync()</code> posts work to it</li><li><code>JUCEApplicationBase</code>: the base of the app lifecycle (<code>JUCEApplication</code> in <code>juce_gui_basics</code> builds on it)</li><li><code>Timer</code>, <code>HighResolutionTimer</code>, <code>MultiTimer</code></li><li><code>AsyncUpdater</code>, <code>ChangeBroadcaster</code>/<code>ChangeListener</code>, <code>ActionBroadcaster</code></li><li>Inter-process communication: <code>InterprocessConnection</code>, <code>ChildProcessCoordinator</code> / <code>ChildProcessWorker</code></li><li><code>ScopedJuceInitialiser_GUI</code>, for starting JUCE&#39;s message system from your own <code>main()</code></li></ul><h3 id="juce-data-structures" tabindex="-1">juce_data_structures <a class="header-anchor" href="#juce-data-structures" aria-label="Permalink to &quot;juce_data_structures {#juce-data-structures}&quot;">​</a></h3><p>Observable data and undo.</p><ul><li><code>ValueTree</code> and <code>ValueTree::Listener</code>: the recommended app-state model</li><li><code>Value</code>, <code>ValueSource</code></li><li><code>UndoManager</code>, <code>UndoableAction</code></li><li><code>PropertiesFile</code>, <code>ApplicationProperties</code>: settings files</li><li><code>ValueTreeSynchroniser</code>: mirror a tree to another process or machine</li></ul><h3 id="juce-cryptography" tabindex="-1">juce_cryptography <a class="header-anchor" href="#juce-cryptography" aria-label="Permalink to &quot;juce_cryptography {#juce-cryptography}&quot;">​</a></h3><p>Hashes and basic crypto: <code>MD5</code>, <code>SHA256</code>, <code>Whirlpool</code>, <code>RSAKey</code>, <code>BlowFish</code>, and <code>Primes</code>. Useful for checksums and licence keys. For security-critical work, use a dedicated, audited library.</p><h3 id="juce-javascript" tabindex="-1">juce_javascript <a class="header-anchor" href="#juce-javascript" aria-label="Permalink to &quot;juce_javascript {#juce-javascript}&quot;">​</a></h3><p><code>JavascriptEngine</code>, an embedded JavaScript interpreter built on QuickJS (via the bundled <code>choc</code> library)<sup class="footnote-ref"><a href="#fn2" id="fnref2">[2]</a></sup>, with <code>JSObject</code> and <code>JSCursor</code> for working with values. Split out of <code>juce_core</code> in 8.0.4. Useful for scripting and user-programmable features.</p><h2 id="graphics-gui" tabindex="-1">Graphics &amp; GUI <a class="header-anchor" href="#graphics-gui" aria-label="Permalink to &quot;Graphics &amp; GUI&quot;">​</a></h2><h3 id="juce-graphics" tabindex="-1">juce_graphics <a class="header-anchor" href="#juce-graphics" aria-label="Permalink to &quot;juce_graphics {#juce-graphics}&quot;">​</a></h3><p>2D drawing, independent of windows and widgets.</p><ul><li><code>Graphics</code>: the drawing context passed to <code>paint()</code></li><li>Geometry: <code>Point</code>, <code>Line</code>, <code>Rectangle</code>, <code>Path</code>, <code>AffineTransform</code>, <code>RectangleList</code></li><li><code>Colour</code>, <code>Colours</code>, <code>ColourGradient</code>, <code>FillType</code></li><li><code>Image</code>, <code>ImageCache</code>, and image formats (PNG, JPEG, GIF, WebP)</li><li><code>Font</code>, <code>FontOptions</code>, <code>GlyphArrangement</code>, <code>TextLayout</code>, <code>AttributedString</code>, with Unicode shaping via HarfBuzz and SheenBidi<sup class="footnote-ref"><a href="#fn2" id="fnref2:1">[2:1]</a></sup></li><li><code>DropShadow</code>, <code>GlowEffect</code></li><li>Native renderers: CoreGraphics (Apple), Direct2D (Windows), and the software renderer</li></ul><h3 id="juce-gui-basics" tabindex="-1">juce_gui_basics <a class="header-anchor" href="#juce-gui-basics" aria-label="Permalink to &quot;juce_gui_basics {#juce-gui-basics}&quot;">​</a></h3><p>The biggest module: the component system and standard widgets.</p><ul><li><strong>Core</strong>: <code>Component</code>, <code>Desktop</code>, <code>ComponentPeer</code>, <code>MouseEvent</code>, <code>KeyPress</code>, <code>FocusTraverser</code></li><li><strong>App and windows</strong>: <code>JUCEApplication</code>, <code>DocumentWindow</code>, <code>ResizableWindow</code>, <code>DialogWindow</code>, <code>AlertWindow</code>, <code>CallOutBox</code></li><li><strong>Widgets</strong>: <code>TextButton</code>, <code>ToggleButton</code>, <code>Slider</code>, <code>ComboBox</code>, <code>Label</code>, <code>TextEditor</code>, <code>ListBox</code>, <code>TableListBox</code>, <code>TreeView</code>, <code>Viewport</code>, <code>TabbedComponent</code>, <code>PopupMenu</code>, <code>MenuBarComponent</code></li><li><strong>Layout</strong>: <code>FlexBox</code>, <code>Grid</code>, <code>ComponentBoundsConstrainer</code>, <code>StretchableLayoutManager</code></li><li><strong>Look and feel</strong>: <code>LookAndFeel</code>, <code>LookAndFeel_V4</code> (the default)<sup class="footnote-ref"><a href="#fn3" id="fnref3">[3]</a></sup></li><li><strong>Drawables</strong>: <code>Drawable</code>, <code>DrawablePath</code>, <code>DrawableImage</code>, with a new SVG parser in JUCE 9<sup class="footnote-ref"><a href="#fn4" id="fnref4">[4]</a></sup></li><li><strong>Other</strong>: <code>FileChooser</code>, <code>ApplicationCommandManager</code> (menus and shortcuts), <code>VBlankAttachment</code>, accessibility support</li></ul><h3 id="juce-gui-extra" tabindex="-1">juce_gui_extra <a class="header-anchor" href="#juce-gui-extra" aria-label="Permalink to &quot;juce_gui_extra {#juce-gui-extra}&quot;">​</a></h3><p>Specialised GUI components, often wrapping native OS features.</p><ul><li><code>WebBrowserComponent</code> plus relays (<code>WebSliderRelay</code>, …) for <strong>WebView UIs</strong></li><li><code>CodeEditorComponent</code>, <code>CodeDocument</code>, <code>CPlusPlusCodeTokeniser</code></li><li>Native embedding: <code>NSViewComponent</code>, <code>HWNDComponent</code>, <code>XEmbedComponent</code>, <code>UIViewComponent</code></li><li><code>SystemTrayIconComponent</code>, <code>PushNotifications</code>, <code>AnimatedAppComponent</code>, <code>ColourSelector</code>, <code>KeyMappingEditorComponent</code>, <code>RecentlyOpenedFilesList</code></li></ul><h3 id="juce-opengl" tabindex="-1">juce_opengl <a class="header-anchor" href="#juce-opengl" aria-label="Permalink to &quot;juce_opengl {#juce-opengl}&quot;">​</a></h3><p>Hardware-accelerated rendering. Attach an <code>OpenGLContext</code> to any component to render its <code>paint()</code> with OpenGL, or implement <code>OpenGLRenderer</code> for custom GL code. Also includes <code>OpenGLShaderProgram</code>, <code>OpenGLTexture</code>, <code>OpenGLFrameBuffer</code>, and <code>OpenGLAppComponent</code>. JUCE 9 added OpenGL ES on Linux.</p><h3 id="juce-animation" tabindex="-1">juce_animation <a class="header-anchor" href="#juce-animation" aria-label="Permalink to &quot;juce_animation {#juce-animation}&quot;">​</a></h3><p>Added in JUCE 8.<sup class="footnote-ref"><a href="#fn4" id="fnref4:1">[4:1]</a></sup> Declarative animations: build an <code>Animator</code> with <code>ValueAnimatorBuilder</code> or <code>AnimatorSetBuilder</code>, then drive it with an <code>AnimatorUpdater</code> or a <code>VBlankAnimatorUpdater</code> synced to the display refresh rate. Includes easing functions.</p><h3 id="juce-video" tabindex="-1">juce_video <a class="header-anchor" href="#juce-video" aria-label="Permalink to &quot;juce_video {#juce-video}&quot;">​</a></h3><p><code>VideoComponent</code> for playback and <code>CameraDevice</code> for capture, built on each platform&#39;s native media APIs.</p><h3 id="juce-box2d" tabindex="-1">juce_box2d <a class="header-anchor" href="#juce-box2d" aria-label="Permalink to &quot;juce_box2d {#juce-box2d}&quot;">​</a></h3><p>The Box2D 2D physics engine, bundled, plus <code>Box2DRenderer</code> to draw a Box2D world with JUCE <code>Graphics</code>. Handy for playful UIs and demos.</p><h2 id="audio-midi" tabindex="-1">Audio &amp; MIDI <a class="header-anchor" href="#audio-midi" aria-label="Permalink to &quot;Audio &amp; MIDI&quot;">​</a></h2><h3 id="juce-audio-basics" tabindex="-1">juce_audio_basics <a class="header-anchor" href="#juce-audio-basics" aria-label="Permalink to &quot;juce_audio_basics {#juce-audio-basics}&quot;">​</a></h3><p>Audio data types and building blocks with no device or file dependencies.</p><ul><li><strong>Buffers</strong>: <code>AudioBuffer&lt;float/double&gt;</code>, <code>FloatVectorOperations</code> (SIMD helpers), <code>AudioChannelSet</code>, <code>AudioData</code> (sample-format conversion)</li><li><strong>MIDI</strong>: <code>MidiMessage</code>, <code>MidiBuffer</code>, <code>MidiMessageSequence</code>, <code>MidiFile</code>, <code>MidiKeyboardState</code>, <strong>MPE</strong> classes, and <strong>MIDI 2.0 Universal MIDI Packets</strong> (<code>ump/</code>)</li><li><strong>Sources</strong>: the <code>AudioSource</code> interface and helpers (<code>MixerAudioSource</code>, <code>ResamplingAudioSource</code>, <code>ToneGeneratorAudioSource</code>, …)</li><li><strong>Synthesis</strong>: <code>Synthesiser</code>, <code>SynthesiserVoice</code>, <code>SynthesiserSound</code>, <code>MPESynthesiser</code></li><li><strong>Utilities</strong>: <code>SmoothedValue</code>, <code>ADSR</code>, <code>Reverb</code>, <code>IIRFilter</code>, <code>Decibels</code>, <code>AudioPlayHead</code></li></ul><h3 id="juce-audio-devices" tabindex="-1">juce_audio_devices <a class="header-anchor" href="#juce-audio-devices" aria-label="Permalink to &quot;juce_audio_devices {#juce-audio-devices}&quot;">​</a></h3><p>Talking to hardware.</p><ul><li><code>AudioDeviceManager</code>: opens and manages the input and output device; the one class most apps need</li><li><code>AudioIODevice</code>, <code>AudioIODeviceType</code>, <code>AudioIODeviceCallback</code></li><li>Backends: CoreAudio (new implementation in JUCE 9)<sup class="footnote-ref"><a href="#fn4" id="fnref4:2">[4:2]</a></sup>, WASAPI, DirectSound, ASIO, ALSA, JACK, Oboe, OpenSL, and iOS audio sessions</li><li>MIDI I/O: <code>MidiInput</code>, <code>MidiOutput</code>, <code>MidiMessageCollector</code>, Bluetooth MIDI, and Windows MIDI Services</li><li><code>AudioSourcePlayer</code>, <code>AudioTransportSource</code></li></ul><h3 id="juce-audio-formats" tabindex="-1">juce_audio_formats <a class="header-anchor" href="#juce-audio-formats" aria-label="Permalink to &quot;juce_audio_formats {#juce-audio-formats}&quot;">​</a></h3><p>Reading and writing audio files.</p><ul><li><code>AudioFormatManager</code>: register formats, then <code>createReaderFor (file)</code></li><li><code>AudioFormatReader</code>, <code>AudioFormatWriter</code>, <code>AudioFormatReaderSource</code>, <code>BufferingAudioReader</code></li><li>Codecs: WAV, AIFF, FLAC, Ogg Vorbis, Opus, MP3 (decoding), CoreAudio and Windows Media (OS codecs), and a LAME-based MP3 encoder wrapper</li><li><code>AudioSubsectionReader</code>, <code>MemoryMappedAudioFormatReader</code>, and ARA audio readers</li></ul><h3 id="juce-dsp" tabindex="-1">juce_dsp <a class="header-anchor" href="#juce-dsp" aria-label="Permalink to &quot;juce_dsp {#juce-dsp}&quot;">​</a></h3><p>Signal-processing building blocks with a common <code>prepare</code> / <code>process</code> / <code>reset</code> interface.</p><ul><li><strong>Framework</strong>: <code>ProcessSpec</code>, <code>ProcessContextReplacing</code>, <code>AudioBlock</code>, <code>ProcessorChain</code>, <code>ProcessorDuplicator</code></li><li><strong>Filters</strong>: <code>IIR::Filter</code>, <code>FIR::Filter</code>, <code>StateVariableTPTFilter</code>, <code>LinkwitzRileyFilter</code>, <code>LadderFilter</code>, and <code>FilterDesign</code></li><li><strong>Effects (&quot;widgets&quot;)</strong>: <code>Gain</code>, <code>Compressor</code>, <code>Limiter</code>, <code>NoiseGate</code>, <code>Chorus</code>, <code>Phaser</code>, <code>Reverb</code>, <code>WaveShaper</code>, <code>Oscillator</code>, <code>DelayLine</code>, <code>DryWetMixer</code>, <code>Panner</code></li><li><strong>Frequency domain</strong>: <code>FFT</code>, <code>Convolution</code> (impulse responses), <code>WindowingFunction</code></li><li><strong>Maths</strong>: <code>Oversampling</code>, <code>LookupTable</code>, <code>FastMathApproximations</code>, <code>Matrix</code>, <code>SIMDRegister</code></li></ul><h3 id="juce-midi-ci" tabindex="-1">juce_midi_ci <a class="header-anchor" href="#juce-midi-ci" aria-label="Permalink to &quot;juce_midi_ci {#juce-midi-ci}&quot;">​</a></h3><p>Added in 7.0.9. An implementation of <strong>MIDI Capability Inquiry</strong>, the MIDI 2.0 negotiation layer: discovery, profiles, and property exchange. The central class is <code>ci::Device</code>.</p><h3 id="juce-osc" tabindex="-1">juce_osc <a class="header-anchor" href="#juce-osc" aria-label="Permalink to &quot;juce_osc {#juce-osc}&quot;">​</a></h3><p>Open Sound Control over UDP: <code>OSCSender</code>, <code>OSCReceiver</code>, <code>OSCMessage</code>, <code>OSCBundle</code>, and <code>OSCAddressPattern</code>. Often used for remote control from apps like TouchOSC, or to link with Max/MSP and SuperCollider.</p><h2 id="plug-ins-hosting" tabindex="-1">Plug-ins &amp; hosting <a class="header-anchor" href="#plug-ins-hosting" aria-label="Permalink to &quot;Plug-ins &amp; hosting&quot;">​</a></h2><h3 id="juce-audio-processors-headless" tabindex="-1">juce_audio_processors_headless <a class="header-anchor" href="#juce-audio-processors-headless" aria-label="Permalink to &quot;juce_audio_processors_headless {#juce-audio-processors-headless}&quot;">​</a></h3><p>The GUI-free core of the plug-in model, split out in 8.0.11.</p><ul><li><code>AudioProcessor</code>: the central interface (see <a href="./../guide/plugin-anatomy.html">Anatomy of a plug-in</a>)</li><li>Parameters: <code>AudioProcessorParameter</code>, <code>RangedAudioParameter</code>, <code>AudioParameterFloat</code> / <code>Int</code> / <code>Bool</code> / <code>Choice</code>, <code>AudioProcessorParameterGroup</code></li><li><code>AudioProcessorGraph</code>: route processors into a network</li><li>Hosting: <code>AudioPluginFormatManager</code>, <code>AudioPluginFormat</code>, <code>AudioPluginInstance</code>, <code>PluginDescription</code>, and headless format implementations (VST3, AU, LV2, LADSPA)</li><li><strong>ARA</strong> support classes, and the bundled VST3 SDK</li></ul><h3 id="juce-audio-processors" tabindex="-1">juce_audio_processors <a class="header-anchor" href="#juce-audio-processors" aria-label="Permalink to &quot;juce_audio_processors {#juce-audio-processors}&quot;">​</a></h3><p>The GUI-dependent half.</p><ul><li><code>AudioProcessorEditor</code>, <code>GenericAudioProcessorEditor</code></li><li><code>AudioProcessorValueTreeState</code> and its <code>SliderAttachment</code>, <code>ButtonAttachment</code>, and <code>ComboBoxAttachment</code></li><li><code>ParameterAttachment</code> and helpers for custom controls</li><li>Scanning: <code>KnownPluginList</code>, <code>PluginDirectoryScanner</code>, <code>PluginListComponent</code></li><li>Format classes that can show a plug-in&#39;s own editor: <code>VST3PluginFormat</code>, <code>AudioUnitPluginFormat</code>, <code>LV2PluginFormat</code>, <code>VSTPluginFormat</code></li></ul><h3 id="juce-audio-plugin-client" tabindex="-1">juce_audio_plugin_client <a class="header-anchor" href="#juce-audio-plugin-client" aria-label="Permalink to &quot;juce_audio_plugin_client {#juce-audio-plugin-client}&quot;">​</a></h3><p>The <strong>format wrappers</strong>: VST3, AU, AUv3, AAX, LV2, VST2, Unity, and Standalone. You never call this module directly. The build system compiles the right wrapper for each format target, and the wrapper calls your <code>createPluginFilter()</code>.</p><h3 id="juce-audio-utils" tabindex="-1">juce_audio_utils <a class="header-anchor" href="#juce-audio-utils" aria-label="Permalink to &quot;juce_audio_utils {#juce-audio-utils}&quot;">​</a></h3><p>Glue and ready-made audio UI.</p><ul><li><code>AudioAppComponent</code>: the quickest way to a standalone audio app</li><li><code>AudioProcessorPlayer</code>: drive an <code>AudioProcessor</code> (or graph) from an audio device</li><li><code>AudioDeviceSelectorComponent</code>: a ready-made audio settings panel</li><li><code>AudioThumbnail</code>, <code>AudioThumbnailCache</code>: waveform displays</li><li><code>MidiKeyboardComponent</code>, <code>MPEKeyboardComponent</code>, <code>AudioVisualiserComponent</code></li><li><code>SoundPlayer</code>, <code>AudioCDReader</code>, <code>BluetoothMidiDevicePairingDialogue</code></li></ul><h2 id="commercial-services" tabindex="-1">Commercial services <a class="header-anchor" href="#commercial-services" aria-label="Permalink to &quot;Commercial services&quot;">​</a></h2><h3 id="juce-analytics" tabindex="-1">juce_analytics <a class="header-anchor" href="#juce-analytics" aria-label="Permalink to &quot;juce_analytics {#juce-analytics}&quot;">​</a></h3><p>Added in 5.2.0. Event tracking for your app: <code>Analytics</code> collects events and forwards them to <code>ThreadedAnalyticsDestination</code> subclasses that you implement to send data to your own back end. <code>ButtonTracker</code> logs button presses.</p><h3 id="juce-product-unlocking" tabindex="-1">juce_product_unlocking <a class="header-anchor" href="#juce-product-unlocking" aria-label="Permalink to &quot;juce_product_unlocking {#juce-product-unlocking}&quot;">​</a></h3><p>Copy protection and purchasing.</p><ul><li><code>OnlineUnlockStatus</code> and <code>OnlineUnlockForm</code>: activate a product against a server</li><li><code>TracktionMarketplaceStatus</code>: an implementation for the Tracktion marketplace</li><li><code>KeyGeneration</code>: generate RSA-signed licence keys</li><li><code>InAppPurchases</code>: the iOS, macOS, and Android store APIs</li></ul><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><p>The class lists above are hand-written from each module&#39;s headers in <a href="https://github.com/juce-framework/JUCE/blob/master/modules" target="_blank" rel="noreferrer"><code>modules/</code></a>; the Doxygen comments there are the authority. Treat any list as a starting point rather than a complete API.</p><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>Generated by <a href="https://github.com/andrewh/JUCE/blob/master/site/scripts/gen-modules.mjs" target="_blank" rel="noreferrer"><code>site/scripts/gen-modules.mjs</code></a> from each <code>BEGIN_JUCE_MODULE_DECLARATION</code> block. <a href="#fnref1" class="footnote-backref">↩︎</a></p></li><li id="fn2" class="footnote-item"><p><a href="https://github.com/juce-framework/JUCE/blob/master/JUCE.spdx.json" target="_blank" rel="noreferrer"><code>JUCE.spdx.json</code></a> lists QuickJS, CHOC, HarfBuzz, and SheenBidi as bundled dependencies; the QuickJS helpers are in <a href="https://github.com/juce-framework/JUCE/blob/master/modules/juce_javascript/detail" target="_blank" rel="noreferrer"><code>modules/juce_javascript/detail</code></a>. <a href="#fnref2" class="footnote-backref">↩︎</a> <a href="#fnref2:1" class="footnote-backref">↩︎</a></p></li><li id="fn3" class="footnote-item"><p><a href="https://github.com/juce-framework/JUCE/blob/master/modules/juce_gui_basics/desktop/juce_Desktop.cpp" target="_blank" rel="noreferrer"><code>juce_Desktop.cpp</code></a>: <code>defaultLookAndFeel.reset (new LookAndFeel_V4());</code>. <a href="#fnref3" class="footnote-backref">↩︎</a></p></li><li id="fn4" class="footnote-item"><p><a href="https://github.com/juce-framework/JUCE/blob/master/CHANGE_LIST.md" target="_blank" rel="noreferrer"><code>CHANGE_LIST.md</code></a>: 9.0.0 (&quot;Added a new SVG parser&quot;, &quot;Added a new macOS CoreAudio implementation&quot;) and 8.0.0 (&quot;Added a new animation module&quot;). <a href="#fnref4" class="footnote-backref">↩︎</a> <a href="#fnref4:1" class="footnote-backref">↩︎</a> <a href="#fnref4:2" class="footnote-backref">↩︎</a></p></li></ol></section>',73))])}const b=c(n,[["render",s]]);export{f as __pageData,b as default};
